// Good: validate the requested file and ensure it stays inside the allowed directory.
import javax.servlet.http.HttpServlet;
import javax.servlet.http.HttpServletRequest;
import javax.servlet.http.HttpServletResponse;
import java.io.BufferedReader;
import java.io.IOException;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;

public class FileServlet extends HttpServlet {
    private static final Path BASE_DIR = Paths.get("/var/data/uploads")
            .toAbsolutePath()
            .normalize();

    @Override
    protected void doGet(HttpServletRequest request, HttpServletResponse response) throws IOException {
        String filename = request.getParameter("file");

        if (filename == null || filename.isEmpty()) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "file parameter is required");
            return;
        }

        // Reject parent-directory traversal and absolute paths before using the file API.
        if (filename.contains("..") || Paths.get(filename).isAbsolute()) {
            response.sendError(HttpServletResponse.SC_BAD_REQUEST, "invalid file name");
            return;
        }

        // Normalize the resolved path and verify that it remains inside BASE_DIR.
        Path securePath = BASE_DIR.resolve(filename).normalize();
        if (!securePath.startsWith(BASE_DIR)) {
            response.sendError(HttpServletResponse.SC_FORBIDDEN, "access denied");
            return;
        }

        if (!Files.isRegularFile(securePath) || !Files.isReadable(securePath)) {
            response.sendError(HttpServletResponse.SC_NOT_FOUND, "file not found");
            return;
        }

        response.setContentType("text/plain");
        try (BufferedReader reader = Files.newBufferedReader(securePath)) {
            String line;
            while ((line = reader.readLine()) != null) {
                response.getWriter().println(line);
            }
        }
    }
}

