(function(){
  var reduced = window.matchMedia('(prefers-reduced-motion: reduce)').matches;

  /* ---- scroll progress ---- */
  var bar = document.getElementById('progress');
  function onScroll(){
    var h = document.documentElement;
    var max = h.scrollHeight - h.clientHeight;
    bar.style.width = (max > 0 ? (h.scrollTop / max) * 100 : 0) + '%';
  }
  document.addEventListener('scroll', onScroll, {passive:true});
  onScroll();

  /* ---- scramble-decode title ---- */
  var scr = document.querySelector('.scramble');
  if (scr){
    var finalText = scr.dataset.text || scr.textContent;
    if (reduced){ scr.textContent = finalText; }
    else {
      var glyphs = 'ATLNS#%&×+ΔΞ';
      var step = 0;
      setTimeout(function(){
        var iv = setInterval(function(){
          var done = true, out = '';
          for (var i = 0; i < finalText.length; i++){
            if (step > i * 4 + 10){ out += finalText[i]; }
            else { done = false; out += glyphs[Math.floor(Math.random() * glyphs.length)]; }
          }
          scr.textContent = out;
          step += 2;
          if (done) clearInterval(iv);
        }, 42);
      }, 250);
    }
  }

  /* ---- reveal + line-mask ---- */
  var io = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (e.isIntersecting){ e.target.classList.add('in'); io.unobserve(e.target); }
    });
  }, {threshold:.18});
  document.querySelectorAll('.reveal, .lm').forEach(function(el){ io.observe(el); });

  /* ---- count-up ---- */
  function fmt(n, dec){
    return n.toLocaleString('en-US', {minimumFractionDigits:dec, maximumFractionDigits:dec});
  }
  var cio = new IntersectionObserver(function(entries){
    entries.forEach(function(e){
      if (!e.isIntersecting) return;
      var el = e.target;
      cio.unobserve(el);
      var target = parseFloat(el.dataset.count);
      var dec = parseInt(el.dataset.decimals || '0', 10);
      if (reduced){ el.textContent = fmt(target, dec); return; }
      var t0 = null, dur = 1500;
      function tick(ts){
        if (!t0) t0 = ts;
        var p = Math.min((ts - t0) / dur, 1);
        var eased = 1 - Math.pow(1 - p, 3);
        el.textContent = fmt(target * eased, dec);
        if (p < 1) requestAnimationFrame(tick);
        else el.textContent = fmt(target, dec);
      }
      requestAnimationFrame(tick);
    });
  }, {threshold:.5});
  document.querySelectorAll('[data-count]').forEach(function(el){ cio.observe(el); });

  /* ---- research-question accordion ---- */
  document.querySelectorAll('.rq-btn').forEach(function(btn){
    btn.addEventListener('click', function(){
      var item = btn.closest('.rq');
      var open = item.classList.toggle('open');
      btn.setAttribute('aria-expanded', open ? 'true' : 'false');
    });
  });
})();
</script>
</body>
